async (page) => {
  const results = []
  const check = (condition, label) => { if (!condition) throw new Error(`FAIL: ${label}`); results.push(label); console.log(`PASS: ${label}`) }
  const state = () => page.evaluate(() => JSON.parse(localStorage.getItem('phyqgen.prototype.v1') || '{}'))
  const row = name => page.locator('.el-table__body tr').filter({ has: page.getByText(name, { exact: true }) })
  const logout = async () => {
    await page.locator('.user-info').hover()
    await page.getByRole('menuitem', { name: '退出登录', exact: true }).click()
    await page.getByRole('dialog', { name: '提示', exact: true }).getByRole('button', { name: '确定', exact: true }).click()
    await page.waitForURL('**/login')
  }
  const login = async (username, password) => {
    await page.getByPlaceholder('请输入用户名', { exact: true }).fill(username)
    await page.getByPlaceholder('请输入密码', { exact: true }).fill(password)
    await page.getByRole('button', { name: '登录', exact: true }).click()
  }
  await login('audit_teacher', 'Audit123')
  await page.getByText('账号已禁用，请联系管理员', { exact: true }).waitFor()
  check(page.url().endsWith('/login'), '禁用账号无法登录')
  await login('admin', 'Admin123')
  await page.waitForURL('**/admin/users')
  await row('audit_teacher').getByRole('button', { name: '编辑', exact: true }).click()
  let dialog = page.getByRole('dialog', { name: '编辑用户', exact: true })
  await dialog.locator('.el-switch__core').click()
  await dialog.getByRole('button', { name: '确定', exact: true }).click()
  await dialog.waitFor({ state: 'hidden' })
  check((await state()).users.find(u => u.username === 'audit_teacher').is_active === true, '重新启用教师账号')
  await row('audit_teacher').getByRole('button', { name: '修改密码', exact: true }).click()
  dialog = page.getByRole('dialog', { name: '修改密码', exact: true })
  await dialog.getByPlaceholder('请输入新密码', { exact: true }).fill('Reset123')
  await dialog.getByRole('button', { name: '确定', exact: true }).click()
  await dialog.waitFor({ state: 'hidden' })
  check((await state()).users.find(u => u.username === 'audit_teacher').password === 'Reset123', '管理员重置教师密码并保存')
  await row('admin').getByRole('button', { name: '删除', exact: true }).click()
  dialog = page.getByRole('dialog', { name: '提示', exact: true })
  await dialog.getByRole('button', { name: '确定', exact: true }).click()
  await page.getByText('不能删除、禁用当前管理员或移除自身管理员角色', { exact: true }).waitFor()
  check((await state()).users.some(u => u.username === 'admin'), '拒绝删除当前管理员')
  await logout()
  await login('audit_teacher', 'Audit123')
  await page.getByText('用户名或密码错误', { exact: true }).waitFor()
  check(page.url().endsWith('/login'), '重置后旧密码无法登录')
  await login('audit_teacher', 'Reset123')
  await page.waitForURL('**/overview')
  check(page.url().endsWith('/overview'), '重置后可用新密码登录')
  await logout()
  await login('admin', 'Admin123')
  await page.waitForURL('**/admin/users')
  await row('audit_teacher').getByRole('button', { name: '删除', exact: true }).click()
  dialog = page.getByRole('dialog', { name: '提示', exact: true })
  check((await state()).users.some(u => u.username === 'audit_teacher'), '删除先弹确认且尚未删除')
  await dialog.getByRole('button', { name: '取消', exact: true }).click()
  check((await state()).users.some(u => u.username === 'audit_teacher'), '取消删除后保留账号')
  await row('audit_teacher').getByRole('button', { name: '删除', exact: true }).click()
  await page.getByRole('dialog', { name: '提示', exact: true }).getByRole('button', { name: '确定', exact: true }).click()
  await row('audit_teacher').waitFor({ state: 'hidden' })
  check(!(await state()).users.some(u => u.username === 'audit_teacher'), '确认删除后账号从列表及本地存储移除')
  await page.screenshot({ path: 'output/playwright/admin-users.png', fullPage: true })
  console.log(JSON.stringify({ phase: 'users-complete', results }, null, 2))
}
